package com.cloudticket.comment.event;
import com.cloudticket.comment.persistence.mapper.CommentMapper; import com.fasterxml.jackson.databind.JsonNode; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component;
@Component public class CommentLikeCountConsumer { private final CommentMapper comments; private final ObjectMapper json; public CommentLikeCountConsumer(CommentMapper c,ObjectMapper j){comments=c;json=j;} @KafkaListener(topics="${cloudticket.comment.like-topic:comment-events}",groupId="${cloudticket.comment.like-group:comment-count-v1}") public void consume(String payload){try{JsonNode n=json.readTree(payload);comments.updateLikeCount(n.path("commentId").asText(),Math.max(0,n.path("likeCount").asInt()));}catch(Exception ignored){}} }
